import{_ as i,C as l,o as t,c as s,a2 as a,b as c,w as o,a as d,E as n,a3 as u}from"./chunks/framework.CAUU6m5Y.js";const A=JSON.parse('{"title":"F4: Real-time Oversell Audit Detector","description":"","frontmatter":{},"headers":[],"relativePath":"features/F4-oversell-audit-detector.md","filePath":"features/F4-oversell-audit-detector.md"}'),m={name:"features/F4-oversell-audit-detector.md"};function v(p,e,h,_,y,b){const r=l("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="f4-real-time-oversell-audit-detector" tabindex="-1">F4: Real-time Oversell Audit Detector <a class="header-anchor" href="#f4-real-time-oversell-audit-detector" aria-label="Permalink to &quot;F4: Real-time Oversell Audit Detector&quot;">​</a></h1><h2 id="technical-overview" tabindex="-1">Technical Overview <a class="header-anchor" href="#technical-overview" aria-label="Permalink to &quot;Technical Overview&quot;">​</a></h2><p>The Oversell Audit Detector (<code>observability/oversell.py</code>) is an autonomous background consistency auditor that continuously scans all inventory records to verify the mathematical conservation invariant: $$\\text{Total Allocated} == \\text{Available} + \\text{Reserved} + \\text{Sold}$$</p><p>If any discrepancy is detected—or if <code>available &lt; 0</code> or <code>sold &gt; total_allocated</code>—an <code>OversellIncident</code> is created, a Prometheus metric <code>oversell_incidents_total</code> is incremented, and a high-severity structured alert is logged.</p>',4)),(t(),c(u,null,{default:o(()=>[n(r,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Scanner%5BPeriodic%20Audit%20Job%5D%20--%3E%20ReadDB%5BQuery%20Inventory%20Record%5D%0A%20%20%20%20ReadDB%20--%3E%20Compute%5BCompute%20sum%20%3D%20available%20%2B%20reserved%20%2B%20sold%5D%0A%20%20%20%20Compute%20--%3E%20Check%7Bsum%20%3D%3D%20total_allocated%20AND%20available%20%3E%3D%200%3F%7D%0A%20%20%20%20Check%20--%3E%7CYes%7C%20InSync%5BStatus%3A%20HEALTHY%5D%0A%20%20%20%20Check%20--%3E%7CNo%7C%20Alert%5BTrigger%20CRITICAL%20OversellIncident%5D%0A%20%20%20%20Alert%20--%3E%20Metric%5BIncrement%20Prometheus%20Gauge%5D%0A%20%20%20%20Alert%20--%3E%20Log%5BStructured%20JSON%20Security%20Log%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="trace-implementation" tabindex="-1">Trace &amp; Implementation <a class="header-anchor" href="#trace-implementation" aria-label="Permalink to &quot;Trace &amp; Implementation&quot;">​</a></h3><ul><li><strong>Source Files</strong>: <code>backend/src/observability/oversell.py:31-106</code>, <code>backend/src/api/app.py:593-616</code></li><li><strong>Key Class</strong>: <code>OversellDetector</code></li><li><strong>Key Methods</strong>: <code>audit_sku(session, sku_id)</code>, <code>audit_all_inventory(session)</code></li><li><strong>API Endpoints</strong>: <code>POST /api/v1/incidents/audit</code>, <code>GET /api/v1/incidents/oversell</code></li></ul><h3 id="say-it-out-loud" tabindex="-1">Say It Out Loud <a class="header-anchor" href="#say-it-out-loud" aria-label="Permalink to &quot;Say It Out Loud&quot;">​</a></h3><blockquote><p>&quot;I built the Real-Time Oversell Detector in <code>src/observability/oversell.py</code> to act as an active consistency monitor over our stock ledger.</p><p>In financial and inventory systems, database check constraints are essential, but you also need automated runtime telemetry to detect data drift caused by edge cases or split-brain partitions.</p><p>My oversell detector performs continuous table audits across all active SKUs. For each record, it verifies that the sum of available, reserved, and sold quantities strictly equals total allocated stock.</p><p>If an invariant anomaly or negative stock count is detected, it logs an immutable incident with the discrepancy delta, publishes a Prometheus metric to alert our on-call team, and allows instant query via <code>GET /api/v1/incidents/oversell</code>.</p><p>This ensures that if any drift ever occurs, it is detected and isolated within seconds.&quot;</p></blockquote>',4))])}const T=i(m,[["render",v]]);export{A as __pageData,T as default};
